/**
 * 专门清洗第二个数组（源数据）的 name
 */
function cleanSourceName(name) {
  if (typeof name !== 'string') return '';
  const hasChinese = /[\u4e00-\u9fa5]/.test(name);
  if (hasChinese) {
    return name.replace(/[^\u4e00-\u9fa5]/g, '');
  } else {
    let cleaned = name.toUpperCase();
    cleaned = cleaned.replace(/\bORDER\b/g, '').replace(/\bNEW\b/g, '');
    return cleaned.replace(/[^A-Z]/g, '');
  }
}

/**
 * 主处理函数：多对一匹配（外层遍历门店，内层遍历源数据）
 */
function matchMultiToOne(storeList, sourceList) {
  const errors = [];

  // 🚀 性能优化：预先清洗第二个数组，提取前5个字母，避免在双重循环中重复计算
  const cleanedSources = sourceList.map(item => {
    const cleaned = cleanSourceName(item.name);
    const prefix5 = cleaned.length >= 3 ? cleaned.slice(0, 3) : cleaned;
    return { ...item, _prefix5: prefix5 };
  });

  // 【关键修正】：外层遍历第一个数组（门店列表），确保每个门店都被检查
  for (let i = 0; i < storeList.length; i++) {
    const storeItem = storeList[i];
    const rawStoreName = storeItem['Store Name'] || storeItem.storeName || '';
    const upperStoreName = rawStoreName.toUpperCase();

    let isMatched = false;

    // 内层遍历第二个数组（源数据），寻找当前门店的匹配项
    for (let j = 0; j < cleanedSources.length; j++) {
      const sourceItem = cleanedSources[j];

      if (!sourceItem._prefix5) continue;

      // 匹配逻辑：门店的大写名称 包含 源数据的前5个字母
      if (upperStoreName.includes(sourceItem._prefix5)) {
        // 匹配成功！写入 id
        storeItem.id = sourceItem.id;
        isMatched = true;
        break; // 找到匹配的源数据后跳出内层循环（因为源数据是唯一的）
      }
    }

    // 如果遍历完所有源数据都没匹配上，记录报错
    if (!isMatched) {
      errors.push(`[匹配失败] 门店 "${rawStoreName}" 在源数据中未找到匹配项`);
    }
  }

  // === 统一报错处理 ===
  if (errors.length > 0) {
    console.error("🚨 === 门店匹配报错 === 🚨");
    errors.forEach(err => console.error(err));
    // 💡 如果需要遇到报错就立刻中断程序，取消下面这行的注释：
    // throw new Error(`匹配中断：共有 ${errors.length} 个门店未能成功匹配！`);
  } else {
    console.log("✅ 所有门店匹配成功！");
  }

  return storeList;
}

